import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"
import { Meta } from "@/components/ui/meta"

type CardProps = React.ComponentProps<"article"> & {
  /**
   * rule: a column under a rule, the giant letter hanging from it.
   * epigraph: someone's words set before the name, the way a book sets a quotation before a chapter.
   * ledger: figures that add up, the total ruled off the way an account is.
   */
  variant?: "rule" | "epigraph" | "ledger"
}

/** A column under a rule, not a box. Point at it and an ink stroke passes along the rule. */
function Card({ variant = "rule", className, ...props }: CardProps) {
  return <article data-slot="card" data-variant={variant} className={cn("db-card", className)} {...props} />
}

/** One giant letter, cropped by the rule like a poster's headline. Decorative. */
function CardFigure({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="card-figure" aria-hidden="true" className={cn("db-card-figure", className)} {...props} />
}

function CardTitle({ className, ...props }: React.ComponentProps<"h3">) {
  return <h3 data-slot="card-title" className={cn("db-card-title", className)} {...props} />
}

/** The link inside the title. Its hit area stretches over the whole card, so the card is one target. */
function CardLink({ className, asChild = false, ...props }: React.ComponentProps<"a"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "a"
  return <Comp data-slot="card-link" className={cn("db-card-link", className)} {...props} />
}

function CardDescription({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="card-description" className={cn("db-card-body", className)} {...props} />
}

/** Ledger figures: pairs of <dt> and <dd> in a <div> each. The last pair is the total. */
function CardSum({ className, ...props }: React.ComponentProps<"dl">) {
  return <dl data-slot="card-sum" className={cn("db-card-sum", className)} {...props} />
}

/** A frame row at the foot: small facts held apart by hairlines. */
function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return <Meta data-slot="card-footer" className={cn("db-card-foot", className)} {...props} />
}

export { Card, CardFigure, CardTitle, CardLink, CardDescription, CardSum, CardFooter, type CardProps }

@layer components {
  /* ── db-card ── a column under a rule, not a box */
  .db-card {
    position: relative; display: grid; align-content: start; gap: var(--db-space-3); padding-top: var(--db-space-4);
    background:
      linear-gradient(var(--db-ink), var(--db-ink)) no-repeat 100% 0 / 0% var(--db-stroke),
      linear-gradient(var(--db-ink), var(--db-ink)) no-repeat 0 0 / 100% var(--db-hairline);
    transition: background-size var(--db-andante) var(--db-exhale), background-position 0s;
  }
  .db-card:is(:has(.db-card-link:is(:hover, :focus-visible)), [data-force~="hover"]) { background-position: 0 0, 0 0; background-size: 100% var(--db-stroke), 100% var(--db-hairline); }
  .db-card:is([dir="rtl"], [dir="rtl"] *) { background-position: 0 0, 0 0; }
  .db-card:is([dir="rtl"], [dir="rtl"] *):is(:has(.db-card-link:is(:hover, :focus-visible)), [data-force~="hover"]) { background-position: 100% 0, 0 0; }
  /* The letter hangs from the rule, its top cut off by it, the way SPECTRA's line cuts its word. */
  .db-card:has(> .db-card-figure:first-child) { padding-top: 0; }
  .db-card-figure { display: flex; align-items: flex-end; height: 0.5em; margin-bottom: var(--db-space-2); overflow: clip; font-size: clamp(6rem, 11vw, 9rem); font-weight: 100; font-stretch: 125%; line-height: 0.76; color: var(--db-ink); user-select: none; }
  .db-card-title { font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 300; color: var(--db-ink); }
  .db-card-link { color: inherit; text-decoration: none; outline: 0; }
  .db-card-link::after { content: ""; position: absolute; inset: 0; }
  .db-card:has(.db-card-link:focus-visible) { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 8px; }
  .db-card-body { max-width: 34ch; }
  .db-card-foot { margin-top: var(--db-space-3); }

  /* Epigraph: their words set before the name, indented to the end of the column, in the italic
     a book gives a quotation before a chapter. The rule moves down to open the chapter: the title. */
  .db-card[data-variant="epigraph"] { background: none; padding-top: 0; }
  .db-card[data-variant="epigraph"] .db-card-body {
    justify-self: end; max-width: min(22ch, 84%);
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-mp) * var(--db-expression-scale)); line-height: 1.3; color: var(--db-ink);
  }
  .db-card[data-variant="epigraph"] .db-card-foot { justify-self: end; flex-wrap: nowrap; gap: var(--db-space-3); margin-top: 0; }
  .db-card[data-variant="epigraph"] .db-card-foot::before { content: ""; flex: none; width: var(--db-space-5); border-top: var(--db-hairline) solid var(--db-rule-strong); }
  .db-card[data-variant="epigraph"] .db-card-title {
    margin-top: var(--db-space-6); padding-top: var(--db-space-4);
    background:
      linear-gradient(var(--db-ink), var(--db-ink)) no-repeat 100% 0 / 0% var(--db-stroke),
      linear-gradient(var(--db-ink), var(--db-ink)) no-repeat 0 0 / 100% var(--db-hairline);
    transition: background-size var(--db-andante) var(--db-exhale), background-position 0s;
  }
  .db-card[data-variant="epigraph"]:is(:has(.db-card-link:is(:hover, :focus-visible)), [data-force~="hover"]) .db-card-title { background-position: 0 0, 0 0; background-size: 100% var(--db-stroke), 100% var(--db-hairline); }
  .db-card[data-variant="epigraph"]:is([dir="rtl"], [dir="rtl"] *) .db-card-title { background-position: 0 0, 0 0; }
  .db-card[data-variant="epigraph"]:is([dir="rtl"], [dir="rtl"] *):is(:has(.db-card-link:is(:hover, :focus-visible)), [data-force~="hover"]) .db-card-title { background-position: 100% 0, 0 0; }

  /* Ledger: the figures add up in a column that is as wide as the total; the total is ruled off
     the way an account is, a single rule over it and a double rule under it, both only as wide as the figures. */
  .db-card[data-variant="ledger"] .db-card-sum { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: baseline; gap: var(--db-space-1) var(--db-space-5); margin: var(--db-space-3) 0 0; font-variant-numeric: tabular-nums lining-nums; }
  .db-card[data-variant="ledger"] .db-card-sum > div { display: contents; }
  .db-card[data-variant="ledger"] .db-card-sum dt { color: var(--db-graphite); }
  .db-card[data-variant="ledger"] .db-card-sum dd { margin: 0; text-align: end; color: var(--db-ink); }
  .db-card[data-variant="ledger"] .db-card-sum > div:last-child > * { margin-top: var(--db-space-3); color: var(--db-ink); }
  .db-card[data-variant="ledger"] .db-card-sum > div:last-child > dd {
    padding: var(--db-space-2) 0 var(--db-space-1);
    font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 200;
    border-top: var(--db-hairline) solid var(--db-ink); border-bottom: calc(3 * var(--db-hairline)) double var(--db-ink);
  }

  /* Forced colours drop background images, so the rule becomes a border. */
  @media (forced-colors: active) {
    .db-card, .db-card[data-variant="epigraph"] .db-card-title { background: none; border-top: var(--db-hairline) solid CanvasText; }
    .db-card[data-variant="epigraph"] { border-top: 0; }
  }
}
